class QuizEngine {
 constructor(questions,clock,uuid,quizId='it-practice-016-020-v2'){this.questions=questions;this.clock=clock;this.uuid=uuid;this.quizId=quizId;this.state=null;this.baseTotal=0;this.baseQuestion=0;}
 start(name){name=name.trim();if(!name)throw Error('Введіть ім’я');const wall=this.clock.wall();this.state={quizId:this.quizId,attemptId:this.uuid(),participantId:this.uuid(),participantName:name,startedAt:new Date(wall).toISOString(),index:0,records:[],done:false,selected:null};this.baseTotal=this.baseQuestion=0;this.anchor=this.clock.now();return this.state;}
 total(){if(!this.state)return 0;if(this.state.done)return this.state.records.at(-1).totalTimeMs;return Math.round(this.baseTotal+Math.max(0,this.clock.now()-this.anchor));}
 questionTime(){return Math.round(this.baseQuestion+Math.max(0,this.clock.now()-this.anchor));}
 select(answerId){const q=this.questions[this.state?.index];if(!q||this.state.done||!q.options.some(o=>o.answerId===answerId))throw Error('Неприпустима відповідь');this.state.selected=answerId;}
 commit(questionId){if(!this.state||this.state.done)return null;const q=this.questions[this.state.index];if(q.questionId!==questionId||!this.state.selected)return null;const option=q.options.find(o=>o.answerId===this.state.selected);const record={submissionId:this.uuid(),quizId:this.quizId,attemptId:this.state.attemptId,participantId:this.state.participantId,participantName:this.state.participantName,articleId:q.articleId,questionId:q.questionId,questionText:q.text,answerId:option.answerId,answerText:option.text,questionTimeMs:this.questionTime(),totalTimeMs:this.total(),startedAt:this.state.startedAt,answeredAt:new Date(this.clock.wall()).toISOString(),delivery:'local'};this.state.records.push(record);this.state.index++;this.state.selected=null;this.state.done=this.state.index===this.questions.length;this.baseTotal=record.totalTimeMs;this.baseQuestion=0;this.anchor=this.clock.now();return record;}
 snapshot(){if(!this.state)return null;return{schema:1,questionSet:this.questions.map(q=>({questionId:q.questionId,optionIds:q.options.map(o=>o.answerId)})),state:JSON.parse(JSON.stringify(this.state)),totalTimeMs:this.total(),questionTimeMs:this.state.done?0:this.questionTime(),savedAt:this.clock.wall()};}
 restore(saved){if(!saved||saved.schema!==1||saved.state?.quizId!==this.quizId)throw Error('Несумісне збереження');const s=saved.state;if(!Array.isArray(s.records)||s.index!==s.records.length||s.index<0||s.index>this.questions.length||s.done!==(s.index===this.questions.length)||!s.participantName?.trim()||!s.attemptId||!s.participantId||!Number.isFinite(Date.parse(s.startedAt)))throw Error('Пошкоджене збереження');for(let i=0;i<s.records.length;i++){const r=s.records[i],q=this.questions[i];if(r.questionId!==q.questionId||!q.options.some(o=>o.answerId===r.answerId)||!Number.isFinite(r.totalTimeMs)||!Number.isFinite(r.questionTimeMs)||r.questionTimeMs<0||r.totalTimeMs<0)throw Error('Пошкоджена відповідь');}if(![saved.totalTimeMs,saved.questionTimeMs,saved.savedAt].every(Number.isFinite)||saved.totalTimeMs<0||saved.questionTimeMs<0)throw Error('Пошкоджений таймер');this.state=JSON.parse(JSON.stringify(s));if(s.selected&&!this.questions[s.index]?.options.some(o=>o.answerId===s.selected))throw Error('Пошкоджений вибір');const gap=s.done?0:Math.max(0,this.clock.wall()-saved.savedAt);this.baseTotal=saved.totalTimeMs+gap;this.baseQuestion=saved.questionTimeMs+gap;this.anchor=this.clock.now();return this.state;}
 score(){return this.state.records.reduce((n,r)=>n+(this.questions.find(q=>q.questionId===r.questionId).correctAnswerId===r.answerId?1:0),0);}
}
function configureQuestions(bank,target,savedSet){
 if(arguments.length===3&&!savedSet)throw Error('Відсутній збережений набір');
 const shuffle=items=>{const out=items.slice();for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]];}return out;};
 let selected;
 if(savedSet){
  if(!Array.isArray(savedSet)||savedSet.length!==20||new Set(savedSet.map(s=>s.questionId)).size!==20)throw Error('Пошкоджений набір питань');
  selected=savedSet.map(s=>{const q=bank.find(q=>q.questionId===s.questionId);if(!q||!Array.isArray(s.optionIds)||s.optionIds.length!==4||new Set(s.optionIds).size!==4||s.optionIds.some(id=>!q.options.some(o=>o.answerId===id)))throw Error('Пошкоджені варіанти');return {...q,options:s.optionIds.map(id=>q.options.find(o=>o.answerId===id))};});
 }else{
  selected=[];for(const articleId of [...new Set(bank.map(q=>q.articleId))])for(const [difficulty,count] of [['easy',1],['medium',2],['hard',1]]){const pool=bank.filter(q=>q.articleId===articleId&&q.difficulty===difficulty);if(pool.length<count)throw Error('Недостатній банк');selected.push(...shuffle(pool).slice(0,count));}
  selected=shuffle(selected).map(q=>({...q,options:shuffle(q.options)}));
 }
 for(const articleId of [...new Set(bank.map(q=>q.articleId))])for(const [difficulty,count] of [['easy',1],['medium',2],['hard',1]])if(selected.filter(q=>q.articleId===articleId&&q.difficulty===difficulty).length!==count)throw Error('Несумісний баланс');
 target.splice(0,target.length,...selected);return target;
};
